const description: { en: string; ja: string } = {"en":"Five pine crowns fill a medium ring. Their flared trunks meet around a single round joint, with narrow openings between the trees.","ja":"中輪の内側を松の冠五つで満たします。裾の広がった幹を一つの丸い節のまわりに寄せ、木の間に細いすき間を残します。"};

